    // END MACHINE VECTORS
    public static int run()throws Exception{
        assertions=0;check(VECTORS.length>0,"Actual native underlay vectors present");Owner last=null;
        for(String vector:VECTORS){DataInputStream in=new DataInputStream(new InflaterInputStream(new ByteArrayInputStream(Base64.getDecoder().decode(vector))));String name=in.readUTF();boolean pixels=in.readBoolean();int[][] effect0=writes(in),effect1=writes(in),controls=writes(in);Snapshot initial=snapshot(in);Owner owner=new Owner(initial,pixels,effect0,effect1,controls);last=owner;String error=null;for(int n=in.readInt();n>0;n--){String op=in.readUTF();int[] args=ints(in);if(error==null)try{owner.operation(op,args);}catch(IOException failure){error=failure.getMessage();}}Snapshot expected=snapshot(in);String nativeError=in.readUTF();check(nativeError.isEmpty()?error==null:error!=null,"Exact native owner boundary "+name+" "+error);owner.compare(expected,name);}
        final Owner owner=last;Pc1Underlay missing=new Pc1Underlay(owner.compositor,owner.ui,null);missing.name(0,0,80,90,2);check(true,"Name mode2 does not require unused effects/controls");missing.body(0,0,80,90,2);check(true,"Body mode2 returns before effects");missing.name(0,0,80,90,0);check(true,"Name draw requires no body effects or controls");owner.compositor.target(0);NativeRgbImage expectedBackground=owner.compositor.rgb(owner.ui.readInt(0x43d418));reject(()->missing.body(0,0,80,90,0),"40FA80");check(owner.compositor.front().rgb(1,2)==expectedBackground.rgb(0,0),"Missing first effect preserves the already completed background copy");check(owner.compositor.front().rgb(3,5)==expectedBackground.rgb(2,3),"Missing first effect stops before actor painting");
        return assertions;
    }
    public static void main(String[] args)throws Exception{System.out.println("PC1 underlay assertions: "+run());}
